import {
  buildGraphTemplateComponents,
  countTemplateParameterSlots,
  isTemplateBuildFailure,
} from "../../waTemplateGraph.ts";
export { countTemplateParameterSlots };
import {
  buildWhatsAppTemplateComponents,
  interpolateDeliveryTemplate,
  type DeliveryContext,
  type WhatsAppTemplateParams,
} from "./buildDeliveryContext.ts";

type ParsedWhatsAppTemplateParams = {
  parameter_values?: string[];
  components_json?: unknown[];
  body?: string[];
  header?: string[];
  button?: string[];
};

function parseStoredWhatsAppTemplateParams(
  raw: Record<string, unknown> | null | undefined,
): ParsedWhatsAppTemplateParams {
  if (!raw || typeof raw !== "object") return {};
  const parameterValues = Array.isArray(raw.parameter_values)
    ? raw.parameter_values.map((v) => String(v ?? ""))
    : undefined;
  const componentsJson = Array.isArray(raw.components_json) ? raw.components_json : undefined;
  const body = Array.isArray(raw.body) ? raw.body.map((v) => String(v ?? "")) : undefined;
  const header = Array.isArray(raw.header) ? raw.header.map((v) => String(v ?? "")) : undefined;
  const button = Array.isArray(raw.button) ? raw.button.map((v) => String(v ?? "")) : undefined;
  return {
    parameter_values: parameterValues,
    components_json: componentsJson,
    body,
    header,
    button,
  };
}

export function validateWhatsAppTemplateParamsForPublish(
  params: Record<string, unknown> | null | undefined,
): string | null {
  const parsed = parseStoredWhatsAppTemplateParams(params);
  const components = parsed.components_json;
  const values = parsed.parameter_values;

  if (Array.isArray(components) && components.length > 0) {
    const expected = countTemplateParameterSlots(components);
    if (expected <= 0) return null;
    if (!Array.isArray(values)) {
      return `Template WhatsApp membutuhkan ${expected} variabel — mapping belum disimpan`;
    }
    if (values.length < expected) {
      return `Template WhatsApp membutuhkan ${expected} variabel, hanya ${values.length} yang diisi`;
    }
    const missing = values.slice(0, expected).some((v) => !String(v ?? "").trim());
    if (missing) return `Lengkapi semua ${expected} variabel template WhatsApp`;
    return null;
  }

  if (Array.isArray(parsed.body) && parsed.body.length > 0) {
    const missing = parsed.body.some((v) => !String(v ?? "").trim());
    if (missing) return "Lengkapi variabel template WhatsApp (format legacy)";
    return null;
  }

  return "Mapping variabel template WhatsApp wajib diisi";
}

/** Flat interpolated template values in Meta {{1}}…{{n}} order (for preview + persist). */
export function getInterpolatedLeadMagnetTemplateValues(
  params: Record<string, unknown> | null | undefined,
  ctx: DeliveryContext,
): string[] | null {
  const parsed = parseStoredWhatsAppTemplateParams(params);
  if (!Array.isArray(parsed.components_json) || parsed.components_json.length === 0) {
    return null;
  }
  const expected = countTemplateParameterSlots(parsed.components_json);
  const rawValues = parsed.parameter_values ?? [];
  if (rawValues.length < expected) return null;
  return rawValues
    .slice(0, expected)
    .map((v) => interpolateDeliveryTemplate(String(v ?? ""), ctx));
}

export function buildLeadMagnetWhatsAppComponents(
  params: Record<string, unknown> | null | undefined,
  ctx: DeliveryContext,
): { ok: true; components: Array<Record<string, unknown>> } | { ok: false; error: string } {
  const parsed = parseStoredWhatsAppTemplateParams(params);

  if (Array.isArray(parsed.components_json) && parsed.components_json.length > 0) {
    const expected = countTemplateParameterSlots(parsed.components_json);
    const rawValues = parsed.parameter_values ?? [];
    if (rawValues.length < expected) {
      return {
        ok: false,
        error: `Template expects ${expected} variable(s) but received ${rawValues.length}.`,
      };
    }
    const interpolated = rawValues
      .slice(0, expected)
      .map((v) => interpolateDeliveryTemplate(String(v ?? ""), ctx));
    const built = buildGraphTemplateComponents(parsed.components_json, interpolated);
    if (isTemplateBuildFailure(built)) {
      return { ok: false, error: built.reason };
    }
    return { ok: true, components: built.components };
  }

  const legacyParams: WhatsAppTemplateParams = {
    body: parsed.body,
    header: parsed.header,
    button: parsed.button,
  };
  return { ok: true, components: buildWhatsAppTemplateComponents(legacyParams, ctx) };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildDeliveryContext, interpolateDeliveryTemplate } from "./buildDeliveryContext.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

function formatResendFrom(displayName: string | undefined, fromEmail: string): string {
  const name = displayName?.trim() || "Synckerja";
  if (fromEmail.includes("<")) return fromEmail;
  return `${name} <${fromEmail}>`;
}

async function resolveOrgEmailFrom(
  admin: SupabaseClient,
  organizationId: string,
  campaignFromName: string | null | undefined,
): Promise<{ from: string; configured: boolean }> {
  const { data: org } = await admin
    .from("organizations")
    .select("lead_magnet_email_from, lead_magnet_email_from_name, name")
    .eq("id", organizationId)
    .maybeSingle();

  const orgFrom = String(org?.lead_magnet_email_from ?? "").trim();
  const envFrom = (Deno.env.get("RESEND_FROM_EMAIL") ?? "onboarding@resend.dev").trim();
  const fromEmail = orgFrom || envFrom;
  const displayName = campaignFromName?.trim()
    || String(org?.lead_magnet_email_from_name ?? "").trim()
    || String(org?.name ?? "").trim()
    || undefined;

  return {
    from: formatResendFrom(displayName, fromEmail),
    configured: Boolean(orgFrom || Deno.env.get("RESEND_FROM_EMAIL")),
  };
}

export async function deliverViaEmail(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    email: string;
  },
): Promise<{ ok: boolean; error?: string }> {
  const resendKey = Deno.env.get("RESEND_API_KEY");
  if (!resendKey) {
    return { ok: false, error: "RESEND_API_KEY is not configured" };
  }

  const to = args.email.trim().toLowerCase();
  if (!to.includes("@")) {
    return { ok: false, error: "Invalid recipient email" };
  }

  const ctx = await buildDeliveryContext(admin, {
    enrollment: args.enrollment,
    campaign: args.campaign,
  });

  const subjectTemplate = args.campaign.email_subject?.trim()
    || "Materi {{campaign_name}} — Synckerja";
  const htmlTemplate = args.campaign.email_html_body?.trim()
    || `<p>Hai {{username}},</p><p>Terima kasih! Berikut link materi kamu:</p><p><a href="{{delivery_url}}">{{delivery_url}}</a></p>`;

  const subject = interpolateDeliveryTemplate(subjectTemplate, ctx);
  const html = interpolateDeliveryTemplate(htmlTemplate, ctx);

  const { from } = await resolveOrgEmailFrom(
    admin,
    args.enrollment.organization_id,
    args.campaign.email_from_name,
  );

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${resendKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from,
      to: [to],
      subject,
      html,
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    console.error("[lead-magnet] Resend error", res.status, text);
    return { ok: false, error: text || "Resend request failed" };
  }
  return { ok: true };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

/** Instagram DM delivery with ≤3s hot-path target (sync before waitUntil). */
export async function deliverViaInstagramDm(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    isFallback?: boolean;
  },
): Promise<boolean> {
  const { sendDeliveryMessage } = await import("../followGateRuntime.ts");
  return sendDeliveryMessage(admin, {
    ...args,
    deliveryChannel: "instagram",
    isFallback: args.isFallback === true,
  });
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { persistLeadWhatsAppThread } from "../../omnichannelPublicApi/persistLeadWhatsAppThread.ts";
import { postTemplateMessage, renderTemplateBodyPreview } from "../../waTemplateGraph.ts";
import { buildDeliveryContext } from "./buildDeliveryContext.ts";
import {
  buildLeadMagnetWhatsAppComponents,
  getInterpolatedLeadMagnetTemplateValues,
} from "./buildLeadMagnetWhatsAppComponents.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

type WhatsAppCredentials = {
  whatsappAccountId: string;
  phoneNumberId: string;
  accessToken: string;
};

async function resolveWhatsAppCredentials(
  admin: SupabaseClient,
  organizationId: string,
  whatsappAccountId: string,
): Promise<WhatsAppCredentials | null> {
  const { data: waAccount } = await admin
    .from("organization_whatsapp_accounts")
    .select("id, phone_number_id, meta_access_token, is_active")
    .eq("id", whatsappAccountId)
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .maybeSingle();

  if (!waAccount?.phone_number_id) return null;

  let accessToken = String(waAccount.meta_access_token ?? "").trim();
  if (!accessToken) {
    const { data: orgMeta } = await admin
      .from("organization_meta_config")
      .select("meta_access_token")
      .eq("organization_id", organizationId)
      .maybeSingle();
    accessToken = String(orgMeta?.meta_access_token ?? "").trim();
  }
  if (!accessToken) return null;

  return {
    whatsappAccountId: String(waAccount.id),
    phoneNumberId: String(waAccount.phone_number_id),
    accessToken,
  };
}

export type DeliverViaWhatsAppTemplateResult =
  | {
      ok: true;
      waMessageId: string;
      conversationId?: string;
      persistError?: string;
      bodyParams: string[];
      rawMetadata: Record<string, unknown>;
    }
  | { ok: false; error: string };

export async function deliverViaWhatsAppTemplate(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    phoneDigits: string;
  },
): Promise<DeliverViaWhatsAppTemplateResult> {
  const accountId = args.campaign.whatsapp_account_id?.trim();
  const templateName = args.campaign.whatsapp_template_name?.trim();
  const templateLanguage = args.campaign.whatsapp_template_language?.trim() || "id";

  if (!accountId || !templateName) {
    return { ok: false, error: "WhatsApp template not configured on campaign" };
  }

  const creds = await resolveWhatsAppCredentials(admin, args.enrollment.organization_id, accountId);
  if (!creds) {
    return { ok: false, error: "WhatsApp account credentials not found" };
  }

  const ctx = await buildDeliveryContext(admin, {
    enrollment: args.enrollment,
    campaign: args.campaign,
  });
  const params = (args.campaign.whatsapp_template_params ?? {}) as Record<string, unknown>;
  const built = buildLeadMagnetWhatsAppComponents(params, ctx);
  if (!built.ok) {
    return { ok: false, error: built.error };
  }

  const bodyParams = getInterpolatedLeadMagnetTemplateValues(params, ctx) ?? [];
  const componentsJson = Array.isArray(params.components_json) ? params.components_json : [];
  const bodyPreview = componentsJson.length > 0
    ? renderTemplateBodyPreview(templateName, componentsJson, bodyParams)
    : `[Template: ${templateName}]`;

  const result = await postTemplateMessage(
    creds.phoneNumberId,
    creds.accessToken,
    args.phoneDigits,
    templateName,
    templateLanguage,
    built.components,
  );

  if (!result.ok) {
    return { ok: false, error: result.body ?? `WA send failed (${result.status})` };
  }

  let conversationId: string | undefined;
  let persistError: string | undefined;

  if (args.enrollment.lead_id) {
    const persisted = await persistLeadWhatsAppThread(admin, {
      organizationId: args.enrollment.organization_id,
      leadId: args.enrollment.lead_id,
      webId: "lead_magnet",
      phoneNumber: args.phoneDigits,
      customerName: args.enrollment.participant_username ?? "Lead",
      waMessageId: result.wa_message_id,
      templateName,
      templateLanguage,
      bodyPreview,
      bodyParams,
      rawMetadata: result.metaData,
      whatsappAccountId: creds.whatsappAccountId,
      phoneNumberId: creds.phoneNumberId,
      leadMagnetMeta: {
        enrollmentId: args.enrollment.id,
        campaignId: args.campaign.id,
      },
    });
    if (persisted.ok) {
      conversationId = persisted.conversationId;
    } else {
      persistError = persisted.error;
      console.error("[lead-magnet] persistLeadWhatsAppThread failed:", persisted.error);
    }
  } else {
    persistError = "Enrollment has no lead_id — livechat thread not created";
    console.warn("[lead-magnet] WA sent without lead_id on enrollment", args.enrollment.id);
  }

  return {
    ok: true,
    waMessageId: result.wa_message_id,
    conversationId,
    persistError,
    bodyParams,
    rawMetadata: result.metaData,
  };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { logLeadMagnetFunnelEvent, updateEnrollmentStatus } from "../funnelAnalytics.ts";
import { upsertParticipantContactField } from "../contactGate/participantProfile.ts";
import { deliverViaEmail } from "./deliverViaEmail.ts";
import { deliverViaInstagramDm } from "./deliverViaInstagramDm.ts";
import { deliverViaWhatsAppTemplate } from "./deliverViaWhatsAppTemplate.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

declare const EdgeRuntime: {
  waitUntil: (promise: Promise<unknown>) => void;
};

function deferDelivery(work: Promise<unknown>): void {
  if (typeof EdgeRuntime !== "undefined" && typeof EdgeRuntime.waitUntil === "function") {
    EdgeRuntime.waitUntil(work);
    return;
  }
  void work;
}

export type DeliveryChannel = "instagram" | "whatsapp" | "email";

export async function runAsyncDelivery(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    channel: "whatsapp" | "email";
    phoneDigits?: string;
    email?: string;
  },
): Promise<void> {
  const startedAt = Date.now();

  if (args.channel === "whatsapp" && args.phoneDigits) {
    const waResult = await deliverViaWhatsAppTemplate(admin, {
      enrollment: args.enrollment,
      campaign: args.campaign,
      phoneDigits: args.phoneDigits,
    });

    if (waResult.ok) {
      await updateEnrollmentStatus(admin, args.enrollment.id, "delivered_whatsapp");
      await upsertParticipantContactField(admin, {
        organizationId: args.enrollment.organization_id,
        platform: args.enrollment.platform,
        participantScopedId: args.enrollment.participant_scoped_id,
        lastDeliveryChannel: "whatsapp",
      });

      const now = new Date().toISOString();
      if (args.enrollment.lead_submission_id) {
        await admin
          .from("lead_submissions")
          .update({
            whatsapp_status: "sent",
            whatsapp_message_id: waResult.waMessageId,
            whatsapp_sent_at: now,
            whatsapp_conversation_id: waResult.conversationId ?? null,
            whatsapp_skip_reason: waResult.persistError ?? null,
            updated_at: now,
          })
          .eq("id", args.enrollment.lead_submission_id);
      }

      await logLeadMagnetFunnelEvent(admin, {
        enrollmentId: args.enrollment.id,
        campaignId: args.campaign.id,
        organizationId: args.enrollment.organization_id,
        eventType: "delivery_whatsapp_sent",
        metadata: {
          wa_message_id: waResult.waMessageId,
          whatsapp_conversation_id: waResult.conversationId ?? null,
          persist_error: waResult.persistError ?? null,
          lm_delivery_latency_ms: Date.now() - startedAt,
        },
      });
      return;
    }

    await logLeadMagnetFunnelEvent(admin, {
      enrollmentId: args.enrollment.id,
      campaignId: args.campaign.id,
      organizationId: args.enrollment.organization_id,
      eventType: "delivery_whatsapp_failed",
      metadata: { error: waResult.error },
    });
    await deliverViaInstagramDm(admin, {
      enrollment: args.enrollment,
      campaign: args.campaign,
      accessToken: args.accessToken,
      pageId: args.pageId,
      isFallback: true,
    });
    return;
  }

  if (args.channel === "email" && args.email) {
    const emailResult = await deliverViaEmail(admin, {
      enrollment: args.enrollment,
      campaign: args.campaign,
      email: args.email,
    });

    if (emailResult.ok) {
      await updateEnrollmentStatus(admin, args.enrollment.id, "delivered_email");
      await upsertParticipantContactField(admin, {
        organizationId: args.enrollment.organization_id,
        platform: args.enrollment.platform,
        participantScopedId: args.enrollment.participant_scoped_id,
        lastDeliveryChannel: "email",
      });
      await logLeadMagnetFunnelEvent(admin, {
        enrollmentId: args.enrollment.id,
        campaignId: args.campaign.id,
        organizationId: args.enrollment.organization_id,
        eventType: "delivery_email_sent",
        metadata: { lm_delivery_latency_ms: Date.now() - startedAt },
      });
      return;
    }

    await logLeadMagnetFunnelEvent(admin, {
      enrollmentId: args.enrollment.id,
      campaignId: args.campaign.id,
      organizationId: args.enrollment.organization_id,
      eventType: "delivery_email_failed",
      metadata: { error: emailResult.error },
    });
    await deliverViaInstagramDm(admin, {
      enrollment: args.enrollment,
      campaign: args.campaign,
      accessToken: args.accessToken,
      pageId: args.pageId,
      isFallback: true,
    });
  }
}

export function scheduleAsyncDelivery(
  admin: SupabaseClient,
  args: Parameters<typeof runAsyncDelivery>[1],
): void {
  deferDelivery(runAsyncDelivery(admin, args));
}

export async function orchestrateDeliveryAfterContact(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    collectedKind: "phone" | "email";
    phoneDigits?: string;
    email?: string;
  },
): Promise<void> {
  if (args.collectedKind === "phone" && args.phoneDigits) {
    scheduleAsyncDelivery(admin, {
      ...args,
      channel: "whatsapp",
      phoneDigits: args.phoneDigits,
    });
    return;
  }
  if (args.collectedKind === "email" && args.email) {
    scheduleAsyncDelivery(admin, {
      ...args,
      channel: "email",
      email: args.email,
    });
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildMetaDeliverySkipReason } from "../../omnichannelPublicApi/syncOmnichannelWhatsAppDelivery.ts";
import { resolveMetaContentAccount } from "../../metaContentAuth.ts";
import { logLeadMagnetFunnelEvent, updateEnrollmentStatus } from "../funnelAnalytics.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";
import { deliverViaInstagramDm } from "./deliverViaInstagramDm.ts";

type LeadMagnetMessageMeta = {
  enrollment_id?: string;
  campaign_id?: string;
  organization_id?: string;
};

/** When Meta reports WA delivery failed, fall back to Instagram DM delivery. */
export async function handleLeadMagnetWhatsAppDeliveryFailed(
  admin: SupabaseClient,
  args: {
    waMessageId: string;
    statusPayload: Record<string, unknown>;
  },
): Promise<void> {
  const waMessageId = args.waMessageId.trim();
  if (!waMessageId) return;

  const { data: msgRow } = await admin
    .from("whatsapp_messages")
    .select("raw_metadata")
    .eq("wa_message_id", waMessageId)
    .maybeSingle();

  const rawMeta = msgRow?.raw_metadata as Record<string, unknown> | undefined;
  const lmMeta = rawMeta?.synckerja_lead_magnet as LeadMagnetMessageMeta | undefined;
  const enrollmentId = String(lmMeta?.enrollment_id ?? "").trim();
  if (!enrollmentId) return;

  const { data: enrollmentRow } = await admin
    .from("lead_magnet_enrollments")
    .select("*, campaign:lead_magnet_campaigns(*)")
    .eq("id", enrollmentId)
    .maybeSingle();

  if (!enrollmentRow) return;

  const enrollment = enrollmentRow as LeadMagnetEnrollmentRow & {
    campaign: LeadMagnetCampaignRow | LeadMagnetCampaignRow[] | null;
  };

  if (enrollment.status === "delivered_instagram" || enrollment.status === "delivered") {
    return;
  }
  if (enrollment.status !== "delivered_whatsapp" && enrollment.status !== "contact_collected") {
    return;
  }

  const campaignRaw = enrollment.campaign;
  const campaign = (Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw) as LeadMagnetCampaignRow | null;
  if (!campaign) return;

  const skipReason = buildMetaDeliverySkipReason(args.statusPayload);
  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId: enrollment.id,
    campaignId: campaign.id,
    organizationId: enrollment.organization_id,
    eventType: "delivery_whatsapp_failed",
    metadata: {
      wa_message_id: waMessageId,
      error: skipReason,
      meta_webhook: true,
    },
  });

  const platform = campaign.platform === "facebook" ? "facebook" : "instagram";
  const account = await resolveMetaContentAccount(
    admin,
    enrollment.organization_id,
    platform,
    campaign.account_id,
  );
  if (!account?.pageAccessToken || !account.pageId) {
    console.error("[lead-magnet] WA failed — cannot resolve Meta account for IG fallback", {
      enrollmentId,
      platform,
      accountId: campaign.account_id,
    });
    return;
  }

  const fallbackOk = await deliverViaInstagramDm(admin, {
    enrollment,
    campaign,
    accessToken: account.pageAccessToken,
    pageId: account.pageId,
    isFallback: true,
  });

  if (!fallbackOk) {
    console.error("[lead-magnet] IG fallback after WA failed did not complete", { enrollmentId });
    return;
  }

  await updateEnrollmentStatus(admin, enrollment.id, "delivered_instagram", {
    last_error: skipReason.slice(0, 500),
  });

  if (enrollment.lead_submission_id) {
    await admin
      .from("lead_submissions")
      .update({
        whatsapp_status: "failed",
        whatsapp_skip_reason: skipReason,
        updated_at: new Date().toISOString(),
      })
      .eq("id", enrollment.lead_submission_id);
  }
}

export const LEAD_MAGNET_ASSETS_BUCKET = "lead-magnet-assets";

export const LEAD_MAGNET_DELIVERY_MAX_BYTES = 25 * 1024 * 1024;

export const LEAD_MAGNET_DELIVERY_ALLOWED_MIMES = new Set([
  "application/pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "application/vnd.openxmlformats-officedocument.presentationml.presentation",
]);

export const LEAD_MAGNET_DELIVERY_ALLOWED_EXTENSIONS = new Set([
  ".pdf",
  ".docx",
  ".xlsx",
  ".pptx",
]);

export type LeadMagnetDeliveryMode = "link" | "upload";

export function parseLeadMagnetDeliveryMode(raw: unknown): LeadMagnetDeliveryMode {
  return String(raw ?? "").trim().toLowerCase() === "upload" ? "upload" : "link";
}

export function buildLeadMagnetAssetPublicUrl(supabaseUrl: string, storagePath: string): string {
  const base = supabaseUrl.replace(/\/+$/, "");
  const encoded = storagePath
    .split("/")
    .map((segment) => encodeURIComponent(segment))
    .join("/");
  return `${base}/storage/v1/object/public/${LEAD_MAGNET_ASSETS_BUCKET}/${encoded}`;
}

export function isAllowedLeadMagnetDeliveryMime(mime: string): boolean {
  return LEAD_MAGNET_DELIVERY_ALLOWED_MIMES.has(mime.trim().toLowerCase());
}

export function isAllowedLeadMagnetDeliveryFileName(name: string): boolean {
  const lower = name.trim().toLowerCase();
  for (const ext of LEAD_MAGNET_DELIVERY_ALLOWED_EXTENSIONS) {
    if (lower.endsWith(ext)) return true;
  }
  return false;
}

export function sanitizeLeadMagnetAssetFileName(name: string): string {
  const base = name.trim().replace(/[/\\?%*:|"<>]/g, "_").replace(/\s+/g, "_");
  return base.slice(0, 120) || "framework";
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  buildLeadMagnetPostbackPayload,
  LEAD_MAGNET_PAYLOAD_PREFIX,
  parseLeadMagnetPostbackPayload,
} from "./types.ts";
import { runLeadMagnetRuntime } from "./runLeadMagnetRuntime.ts";

type ActiveEnrollmentRow = {
  id: string;
  status: string;
  lead_magnet_campaigns: {
    follow_button_label: string;
    framework_button_label: string;
  } | {
    follow_button_label: string;
    framework_button_label: string;
  }[] | null;
};

function normalizeLabel(value: string): string {
  return value.trim().toLowerCase();
}

async function findActiveFacebookEnrollment(
  admin: SupabaseClient,
  organizationId: string,
  participantScopedId: string,
): Promise<{ id: string; followLabel: string; frameworkLabel: string } | null> {
  const { data } = await admin
    .from("lead_magnet_enrollments")
    .select(`
      id,
      status,
      lead_magnet_campaigns!inner (
        follow_button_label,
        framework_button_label
      )
    `)
    .eq("organization_id", organizationId)
    .eq("platform", "facebook")
    .eq("participant_scoped_id", participantScopedId)
    .in("status", ["comment_replied", "follow_checked", "follow_gate_sent", "follow_validated", "framework_offered"])
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (!data?.id) return null;
  const row = data as ActiveEnrollmentRow;
  const campaignRaw = row.lead_magnet_campaigns;
  const campaign = Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw;
  if (!campaign) return null;

  return {
    id: String(row.id),
    followLabel: String(campaign.follow_button_label ?? ""),
    frameworkLabel: String(campaign.framework_button_label ?? ""),
  };
}

export async function resolveLeadMagnetFacebookPostbackPayload(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    participantScopedId: string;
    payload: string;
    title: string;
  },
): Promise<string | null> {
  const payload = args.payload.trim();
  if (payload.startsWith(LEAD_MAGNET_PAYLOAD_PREFIX)) {
    return payload;
  }

  const title = args.title.trim();
  if (!title) return null;

  const enrollment = await findActiveFacebookEnrollment(admin, args.organizationId, args.participantScopedId);
  if (!enrollment) return null;

  const normalizedTitle = normalizeLabel(title);
  if (enrollment.followLabel && normalizedTitle === normalizeLabel(enrollment.followLabel)) {
    return buildLeadMagnetPostbackPayload(enrollment.id, "follow_confirm");
  }
  if (enrollment.frameworkLabel && normalizedTitle === normalizeLabel(enrollment.frameworkLabel)) {
    return buildLeadMagnetPostbackPayload(enrollment.id, "get_framework");
  }

  return null;
}

export async function resolveLeadMagnetFacebookTextPayload(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    participantScopedId: string;
    text: string;
  },
): Promise<string | null> {
  const text = args.text.trim();
  if (!text) return null;

  const enrollment = await findActiveFacebookEnrollment(admin, args.organizationId, args.participantScopedId);
  if (!enrollment) return null;

  const normalized = normalizeLabel(text);
  if (enrollment.followLabel && normalized === normalizeLabel(enrollment.followLabel)) {
    return buildLeadMagnetPostbackPayload(enrollment.id, "follow_confirm");
  }
  if (enrollment.frameworkLabel && normalized === normalizeLabel(enrollment.frameworkLabel)) {
    return buildLeadMagnetPostbackPayload(enrollment.id, "get_framework");
  }

  return null;
}

export async function runLeadMagnetFacebookPostbackIfResolved(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    accountId: string;
    pageId: string;
    participantScopedId: string;
    payload: string;
    accessToken: string;
  },
): Promise<boolean> {
  const parsed = parseLeadMagnetPostbackPayload(args.payload);
  if (!parsed) {
    console.warn("[lead-magnet] invalid facebook postback payload", args.payload.slice(0, 80));
    return false;
  }

  return runLeadMagnetRuntime(admin, {
    trigger: "postback",
    platform: "facebook",
    organizationId: args.organizationId,
    accountId: args.accountId,
    participantScopedId: args.participantScopedId,
    participantUsername: null,
    payload: args.payload,
    accessToken: args.accessToken,
    pageId: args.pageId,
  });
}

import {
